/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import shutil
import sqlite3
import tempfile

root = Path.cwd()
backup = Path(tempfile.mkdtemp(prefix='.transfer-baseline-', dir=root))
for name in ('vault.py', 'app.py'):
    shutil.copyfile(root / name, backup / (name + '.before'))
print('Baseline copies:', backup.name)
print('SQLite:', sqlite3.sqlite_version)
print('Binding update hook:', hasattr(sqlite3.Connection, 'set_update_hook'))
with sqlite3.connect(':memory:') as con:
    con.executescript('''
        PRAGMA recursive_triggers=ON;
        CREATE TABLE probe (id INTEGER PRIMARY KEY, name TEXT UNIQUE);
        CREATE TABLE effects (operation TEXT, id INTEGER, name TEXT);
        CREATE TRIGGER observe_insert AFTER INSERT ON probe BEGIN
          INSERT INTO effects VALUES ('insert', NEW.id, NEW.name);
        END;
        CREATE TRIGGER observe_delete AFTER DELETE ON probe BEGIN
          INSERT INTO effects VALUES ('delete', OLD.id, OLD.name);
        END;
        INSERT INTO probe VALUES (1, 'occupied');
        DELETE FROM effects;
    ''')
    con.execute(\"INSERT OR IGNORE INTO probe VALUES (2, 'occupied')\")
    assert con.execute('SELECT * FROM effects').fetchall() == []
    con.execute(\"INSERT OR REPLACE INTO probe VALUES (2, 'occupied')\")
    assert con.execute('SELECT * FROM effects ORDER BY rowid').fetchall() == [
        ('delete', 1, 'occupied'), ('insert', 2, 'occupied')]
    print('Actual-effect probe: ignored insert has no effects; unique-key replacement exposes delete and insert.')
PY"

